import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel source
_cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void matvec_fp16_kernel(const half* __restrict__ A,
                                   const half* __restrict__ B,
                                   half* __restrict__ C,
                                   int M, int K) {
    int row = blockIdx.x;               // one block per output row
    int tid = threadIdx.x;
    float sum = 0.0f;

    // stride over K dimension
    for (int col = tid; col < K; col += blockDim.x) {
        half a = A[row * K + col];
        half b = B[col];
        sum += __half2float(a) * __half2float(b);
    }

    // block‑wide reduction in shared memory
    extern __shared__ float shmem[];
    shmem[tid] = sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shmem[tid] += shmem[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        C[row] = __float2half(shmem[0]);
    }
}

torch::Tensor matvec_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "matvec_fp16 expects half‑precision tensors");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "matvec_fp16 expects CUDA tensors");

    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::empty({M, 1}, A.options());

    const int threads = 256;
    const dim3 blocks(M);
    const size_t shared_mem = threads * sizeof(float);

    AT_DISPATCH_HALF_TYPES(A.scalar_type(), "matvec_fp16_kernel", ([&] {
        matvec_fp16_kernel<<<blocks, threads, shared_mem,
                             at::cuda::getCurrentCUDAStream()>>>(
            A.data_ptr<half>(),
            B.data_ptr<half>(),
            C.data_ptr<half>(),
            M,
            K);
    }));

    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matvec_fp16", &matvec_fp16, "Matrix‑vector multiplication (fp16, CUDA)");
}
'''

# Compile the inline extension
_matvec_module = load_inline(
    name='matvec_fp16_ext',
    cpp_sources='',
    cuda_sources=_cuda_source,
    functions=['matvec_fp16'],
    verbose=False,
)

class ModelNew(torch.nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    All tensors must be half‑precision (torch.float16) and reside on the GPU.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Args:
            A: Tensor of shape (M, K), dtype torch.float16, device cuda
            B: Tensor of shape (K, 1), dtype torch.float16, device cuda

        Returns:
            Tensor of shape (M, 1), dtype torch.float16, device cuda
        """
        return _matvec_module.matvec_fp16(A, B)

# Export for external use
__all__ = ['ModelNew']
